package com.coffeeshop.service;import com.coffeeshop.dto.PurchasingCommands;import com.coffeeshop.model.PurchasingModels;import com.coffeeshop.repository.PurchasingRepository;import java.math.*;import java.util.*;public final class PurchasingService{private final PurchasingRepository repository;public PurchasingService(PurchasingRepository r){repository=Objects.requireNonNull(r);}public PurchasingModels.Catalog catalog(){return repository.load();}public long saveSupplier(PurchasingCommands.Supplier q){Objects.requireNonNull(q);if(q.id()!=null&&empty(q.version()))throw new IllegalArgumentException("Refresh this supplier and try again.");String email=optional(q.email(),254,"Email");if(email!=null&&(!email.contains("@")||email.startsWith("@")||email.endsWith("@")))throw new IllegalArgumentException("Enter a valid email address.");return repository.saveSupplier(new PurchasingCommands.Supplier(q.id(),required(q.code(),50,"Supplier code"),required(q.name(),200,"Supplier name"),optional(q.contact(),150,"Contact person"),optional(q.phone(),30,"Phone"),email,optional(q.address(),500,"Address"),optional(q.notes(),1000,"Notes"),q.active(),q.version()));}public void setSupplierActive(PurchasingModels.Supplier s,boolean active){Objects.requireNonNull(s);repository.setSupplierActive(s.id(),active,s.version());}public long saveDraft(PurchasingCommands.Purchase q,long user){Objects.requireNonNull(q);if(q.supplierId()<=0||user<=0)throw new IllegalArgumentException("Select a supplier.");if(q.purchasedAt()==null)throw new IllegalArgumentException("Purchase date is required.");if(q.id()!=null&&empty(q.version()))throw new IllegalArgumentException("Refresh this purchase and try again.");if(q.items().isEmpty())throw new IllegalArgumentException("Add at least one purchase item.");Set<Long>ids=new HashSet<>();List<PurchasingCommands.Line>lines=q.items().stream().map(x->{if(x.itemId()<=0||!ids.add(x.itemId()))throw new IllegalArgumentException("Each inventory item may appear only once.");BigDecimal qty=positive(x.quantity(),"Quantity"),cost=nonnegative(x.unitCost(),"Unit cost");return new PurchasingCommands.Line(x.id(),x.itemId(),qty,cost,x.version());}).toList();BigDecimal subtotal=lines.stream().map(x->x.quantity().multiply(x.unitCost()).setScale(4,RoundingMode.HALF_UP)).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal discount=nonnegative(q.discount(),"Discount"),tax=nonnegative(q.tax(),"Tax");if(discount.compareTo(subtotal)>0)throw new IllegalArgumentException("Discount cannot exceed subtotal.");return repository.saveDraft(new PurchasingCommands.Purchase(q.id(),q.supplierId(),q.purchasedAt(),discount,tax,optional(q.invoice(),100,"Supplier invoice"),optional(q.notes(),1000,"Notes"),lines,q.version()),user);}public void receive(PurchasingModels.Purchase p,long user){if(!"DRAFT".equals(p.status()))throw new IllegalStateException("Only draft purchases can be received.");repository.receive(p.id(),user,p.version());}public void cancel(PurchasingModels.Purchase p){if(!"DRAFT".equals(p.status()))throw new IllegalStateException("Only draft purchases can be cancelled.");repository.cancel(p.id(),p.version());}private static BigDecimal positive(BigDecimal v,String n){v=nonnegative(v,n);if(v.signum()==0)throw new IllegalArgumentException(n+" must be greater than zero.");return v;}private static BigDecimal nonnegative(BigDecimal v,String n){if(v==null||v.signum()<0)throw new IllegalArgumentException(n+" cannot be negative.");return v.setScale(4,RoundingMode.HALF_UP);}private static boolean empty(byte[]v){return v==null||v.length==0;}private static String required(String v,int m,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>m)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int m,String n){return v==null||v.isBlank()?null:required(v,m,n);}}
